<?php
namespace Delnavazan\Platform\Core\Application; use Delnavazan\Platform\Core\Infrastructure\Repository\TeacherRepository;
final class TeacherService { public function create(array $d):int{if(!current_user_can('dzn_manage_teachers'))throw new \RuntimeException('Unauthorized');$d['status']=Normalizer::one($d['status']??'active',['active','inactive'],'teacher state');$d['display_name']=Normalizer::text($d['display_name']??'',191,true);$d['email']=Normalizer::email($d['email']??null);$d['country_code']=Normalizer::country($d['country_code']??'IR');$d['timezone']=Normalizer::timezone($d['timezone']??'Asia/Tehran');$d['calendar_preference']=Normalizer::one($d['calendar_preference']??'persian',['auto','gregorian','persian'],'calendar');return Creator::create(new TeacherRepository,$d,'DZN-TCH-');} }
